// @local/dsh-qqbot-user-questions
// 为 qqbot 提供 userQuestions provider，让 extra-plan 的 ask_user_question
// 在 QQ 上真实问答往返，闸门语义完全保留。
//
// 设计依据（方案 v4 已探查核实）：
// - dsh-qqbot bootstrap.js 由主会话在步骤 2 中执行 ctx.provide 导出 bot 与 sessionManager
// - QQBot.js L349-353：消息链 = [...this.middlewares, emit('message')]，
//   bot.use() 注册的 middleware 天然先于 message 事件执行，不调 next() 即短路
// - session-manager.js L295-301：manager.findByAgent(agent) 反查 QQ peer record
// - dsh-extra-plan/index.js L76-80、L239-258：闸门用 indexOf 包含匹配固定词 label
import { UserQuestionError } from '@deepseek-ai/dsh-user-questions'

export const name = 'dsh-qqbot-user-questions'
export const inject = ['qqbot.bot', 'qqbot.sessionManager', 'userQuestions']

export function apply(ctx, config) {
  const bot = ctx['qqbot.bot']
  const manager = ctx['qqbot.sessionManager']
  const userQuestions = ctx.userQuestions

  // ── 待处理问题映射：key = `${scope}:${peerId}` → entry ──
  // entry = {
  //   resolve, reject, signal, cleanupSignal,
  //   labels, ids,           // 选择阶段用（扁平化选项 label/id）
  //   questions,             // 原始 questions 数组
  //   stage: 'select',       // 'select' | 'freetext'
  //   selectedAnswer: null,  // 选择阶段的解析结果 [{id, selected, custom}]
  //   scope, peerId,         // 用于发送追问消息
  // }
  const pending = new Map()

  // ── 1) 注册 QQBot middleware（拦截答案消息，两阶段处理）──
  // QQBot.js L349-353：消息链 = [...this.middlewares, emit('message')]
  // bot.use() 注册的 middleware 天然先于 message 事件，不调 next() 即短路
  bot.use(async (mwCtx, next) => {
    const msg = mwCtx.message
    // 与 session-manager 的 scope/peerId 语义保持一致：
    // group 消息用 groupOpenid（回退 senderId），c2c 用 senderId
    const scope = msg.kind === 'group' ? 'group' : 'c2c'
    const peerId = scope === 'group' ? (msg.groupOpenid ?? msg.senderId) : msg.senderId
    const key = `${scope}:${peerId}`
    const entry = pending.get(key)

    if (entry === undefined) {
      // 不是答案消息，放行给正常消息处理
      return next()
    }

    const text = (msg.content ?? '').trim()

    // ── 选择阶段 ──
    if (entry.stage === 'select') {
      if (text.length === 0) return next()  // 空消息放行

      const answer = parseSelectAnswer(text, entry.labels, entry.ids)
      if (answer === null) return next()  // 解析失败放行

      entry.selectedAnswer = answer

      // 判断是否需要追问
      const needFreetext = shouldTriggerFreetext(entry.questions, answer)
      if (needFreetext) {
        // 进入追问阶段（无超时，与 dsh 原生一致：一直等，取消靠 signal）
        entry.stage = 'freetext'
        const freetextQ = entry.questions.find(q => !q.options || q.options.length === 0)
        const promptText = formatFreetextPrompt(freetextQ)
        await bot.sendText({ scope: entry.scope, targetId: entry.peerId }, promptText)
      } else {
        // 不需要追问，直接 resolve
        pending.delete(key)
        if (entry.cleanupSignal) entry.cleanupSignal()
        entry.resolve({ answers: mergeAnswers(entry.questions, entry.selectedAnswer, null) })
      }
      return  // 短路，消息不会到达 dsh-qqbot 的 message 事件处理器
    }

    // ── 追问阶段 ──
    if (entry.stage === 'freetext') {
      pending.delete(key)
      if (entry.cleanupSignal) entry.cleanupSignal()
      // 追问结果：非空时用原文，空时传 null（mergeAnswers 中设 undefined）
      const freetextResult = text.length > 0 ? text : null
      entry.resolve({ answers: mergeAnswers(entry.questions, entry.selectedAnswer, freetextResult) })
      return  // 短路
    }
  })

  // ── 2) 注册 userQuestions provider ──
  const dispose = userQuestions.registerProvider({
    async ask(request) {
      // 2a) 从 agent 反查 QQ peer（使用 SessionManager 现成方法 L295-301）
      const record = manager.findByAgent(request.agent)
      if (record === undefined) {
        throw new UserQuestionError(
          '无法找到该 agent 对应的 QQ 会话',
          'NO_PROVIDER'
        )
      }
      const scope = record.scope
      const peerId = record.peerId

      // 2b) 格式化问题为文字列表 + 收集选项 label（只列有选项 question）
      const { text, labels, ids } = formatSelectMessage(request.questions)
      const key = `${scope}:${peerId}`

      // 2c) 发送问题到 QQ
      await bot.sendText(
        { scope, targetId: peerId },
        text
      )

      // 2d) 等待用户回复（Promise）
      return new Promise((resolve, reject) => {
        const entry = {
          resolve, reject,
          signal: request.signal,
          labels, ids,
          questions: request.questions,
          stage: 'select',
          selectedAnswer: null,
          cleanupSignal: undefined,
          scope, peerId,
        }

        // signal abort 处理（与 dsh 原生一致：无超时，取消靠 exec.signal）
        if (request.signal) {
          const onAbort = () => {
            pending.delete(key)
            reject(new UserQuestionError('ask_user_question 被取消', 'ASK_ABORTED'))
          }
          request.signal.addEventListener('abort', onAbort, { once: true })
          entry.cleanupSignal = () =>
            request.signal.removeEventListener('abort', onAbort)
        }

        pending.set(key, entry)
      })
    }
  })

  // ── 3) 生命周期清理 ──
  ctx.effect(() => {
    return () => {
      dispose()
      for (const [, entry] of pending) {
        entry.reject(new UserQuestionError('插件已卸载', 'NO_PROVIDER'))
      }
      pending.clear()
    }
  }, 'dsh-qqbot-user-questions.lifecycle')
}

// ── 辅助函数 ──

/**
 * 只列有选项 question：遍历 questions，仅对 q.options 非空的 question
 * 生成编号列表；无选项 question（如 feedback 补充说明）不显示。
 * 返回 { text, labels, ids }。
 */
function formatSelectMessage(questions) {
  const lines = ['📋 **请选择：**', '']
  const labels = []  // 扁平化收集所有选项 label
  const ids = []     // 并行收集每个选项对应的 question id
  for (const q of questions) {
    if (!q.options || q.options.length === 0) continue  // 跳过无选项
    if (q.header) lines.push(`**${q.header}**`)
    lines.push(q.question)
    for (const opt of q.options) {
      labels.push(opt.label)
      ids.push(q.id)
      lines.push(`${labels.length}. ${opt.label}`)
    }
    lines.push('')
  }
  lines.push('---')
  lines.push('请回复数字')
  return { text: lines.join('\n'), labels, ids }
}

/**
 * 追问消息模板：提示用户直接回复文本，无需补充请留空。
 */
function formatFreetextPrompt(question) {
  const header = question.header || question.question
  return `📝 **补充说明：${header}**\n\n请直接回复文本内容，无需补充请留空。`
}

/**
 * 是否触发追问：双条件同时满足才追问。
 * 条件1：selectedAnswer 中任一 label 包含「转交pro规划」（indexOf 包含匹配，与闸门一致）
 * 条件2：questions 中存在至少一个无选项 question
 */
function shouldTriggerFreetext(questions, selectedAnswer) {
  // 条件1：用户选了「转交pro规划」
  const hasReplan = selectedAnswer.some(a =>
    a.selected && a.selected.some(label => label.indexOf('转交pro规划') !== -1)
  )
  if (!hasReplan) return false

  // 条件2：存在无选项 question
  const hasFreetextQ = questions.some(q => !q.options || q.options.length === 0)
  return hasFreetextQ
}

/**
 * 合并选择阶段与追问阶段结果，返回完整 answers 数组（长度 = questions.length）。
 * 有选项 question：用 selectedAnswer 中按 id 匹配的结果。
 * 无选项 question：custom = 追问结果原文（不加任何前缀/标记），空时为 undefined。
 */
function mergeAnswers(questions, selectedAnswer, freetextResult) {
  return questions.map(q => {
    // 有选项 question：从 selectedAnswer 中找匹配
    if (q.options && q.options.length > 0) {
      const match = selectedAnswer.find(a => a.id === q.id)
      if (match) return match
      return { id: q.id, selected: [], custom: undefined }
    }
    // 无选项 question：追问结果原文（不加任何前缀/标记）
    return {
      id: q.id,
      selected: [],
      custom: freetextResult !== null ? freetextResult : undefined
    }
  })
}

/**
 * 解析选择阶段数字回复，返回 AskUserQuestionAnswerItem[]。
 * 纯数字 → 按全局序号取 labels[idx] 放进 selected，id 用 ids[idx]。
 * 非纯数字或数字越界 → 返回 null（放行消息，不消费 pending）。
 *
 * 闸门 matchRouteLabel/matchApprovalLabel 使用 indexOf 包含匹配
 * （dsh-extra-plan/index.js L239-258），所以 selected 里放的是完整固定词 label。
 */
function parseSelectAnswer(text, labels, ids) {
  const trimmed = text.trim()

  // 纯数字回复
  const numMatch = trimmed.match(/^\d+$/)
  if (!numMatch) return null  // 非纯数字：放行

  const idx = parseInt(numMatch[0], 10) - 1
  if (idx < 0 || idx >= labels.length) return null  // 数字越界：放行

  return [{ id: ids[idx], selected: [labels[idx]], custom: undefined }]
}
